//! What the gate (admin, `save_as`) needs to know about a model, on the
//! SeaORM entity itself.
//!
//! A trait, not a second model. For a project's models it is generated by
//! `model!{}`, from the same source as the forms; Runique implements it by
//! hand for its own tables. Kept thin: display belongs to the builder.
use crate::utils::constante::resource_key;
use sea_orm::{EntityTrait, PrimaryKeyTrait};
use std::str::FromStr;

/// `FromStr` on the key: a row's id arrives as URL text, each model parses it
/// with its own key type (`i32`, `Uuid`…). A composite key can't, so such a
/// table can't be registered: a compile error, not a runtime one.
pub trait ModelMeta:
    EntityTrait<Model: Sync, PrimaryKey: PrimaryKeyTrait<ValueType: Clone + PartialEq + Sync + FromStr>>
{
    /// Resource key, also the rights key in `eihwaz_groupes_droits`.
    const KEY: &'static str;
    /// Column holding the owner's id. Without one, `can_*_own` rights never
    /// open anything on this model.
    const OWNER: Option<Self::Column> = None;
    /// `eihwaz_users`: its superuser accounts are protected by the gate.
    const IS_ACCOUNT_TABLE: bool = false;
    /// Columns never shown, searched, filtered, sorted or written through the
    /// gate (a password hash). Even unshown, a searchable or sortable secret is an
    /// oracle: rows coming back for a guessed prefix give the value away.
    const SECRET: &'static [Self::Column] = &[];
    /// A table of Runique's own (accounts, groups, rights): its rights come
    /// from the rank, never from a group — a group granting itself rights on
    /// them would be a privilege escalation.
    const IS_FRAMEWORK_TABLE: bool = false;
    /// The model's form: generated by `model!{}` / `extend!{}` from the
    /// model's own fields (`{Model}ModelForm`). The admin builds from no other one.
    type Form: crate::forms::field::RuniqueForm;
    /// The model's columns as the migration creates them: nullability;
    /// default, auto_now. The entity alone doesn't know a column's default.
    fn schema() -> crate::migration::schema::ModelSchema;
}

impl ModelMeta for crate::auth::user::Entity {
    const KEY: &'static str = resource_key::USERS;
    type Form = crate::auth::form::UserModelForm;
    const IS_ACCOUNT_TABLE: bool = true;
    const SECRET: &'static [Self::Column] = &[crate::auth::user::Column::Password];
    const IS_FRAMEWORK_TABLE: bool = true;
    fn schema() -> crate::migration::schema::ModelSchema {
        crate::auth::user::schema()
    }
}
